/// Native request objects belong to one wl_surface, never to a desktop name.
#[derive(Default)]
struct BackgroundBlur {
    kde: Option<org_kde_kwin_blur::OrgKdeKwinBlur>,
    ext: Option<ext_background_effect_surface_v1::ExtBackgroundEffectSurfaceV1>,
}

impl BackgroundBlur {
    fn clear(&mut self) {
        if let Some(effect) = self.ext.take() { effect.destroy(); }
        if let Some(blur) = self.kde.take() { blur.release(); }
    }

    fn update(
        &mut self,
        effects: &crate::linux::BackgroundEffects,
        surface: &wl_surface::WlSurface,
        qh: &wayland_client::QueueHandle<WaylandClientStatePtr>,
        region: &wayland_client::protocol::wl_region::WlRegion,
        requested: bool,
    ) {
        let blurred = requested && effects.supports_blur();
        if let Some(manager) = &effects.ext {
            if blurred {
                let effect = self.ext.get_or_insert_with(|| {
                    manager.get_background_effect(surface, qh, ())
                });
                // ext starts empty; null REMOVES blur. Copy a surface-local
                // region on creation/resize before the next wl_surface.commit.
                effect.set_blur_region(Some(region));
            } else if let Some(effect) = self.ext.take() {
                effect.destroy();
            }
        } else if let Some(effect) = self.ext.take() {
            effect.destroy();
        }
        if let Some(manager) = &effects.kde {
            if blurred && effects.ext.is_none() {
                let blur = self.kde.get_or_insert_with(|| manager.create(surface, qh, ()));
                blur.set_region(Some(region));
                blur.commit();
            } else {
                manager.unset(surface);
                if let Some(blur) = self.kde.take() { blur.release(); }
            }
        } else if let Some(blur) = self.kde.take() {
            blur.release();
        }
    }
}

