#[cfg(test)]
mod background_blur_tests {
    use super::*;
    use crate::linux::BackgroundEffects;
    use std::{io::Read, os::unix::net::UnixStream};
    use wayland_client::{Connection, delegate_noop, protocol::{wl_compositor, wl_registry}};
    use wayland_protocols::ext::background_effect::v1::client::ext_background_effect_manager_v1;
    use wayland_protocols_plasma::blur::client::org_kde_kwin_blur_manager;

    // No display/GPU/compositor. Capture the actual generated Wayland requests
    // made by the production region/lifetime implementation over a socket pair.
    delegate_noop!(WaylandClientStatePtr: ignore wl_registry::WlRegistry);

    fn requests(connection: &Connection, server: &mut UnixStream) -> Vec<(u32, u16, Vec<u32>)> {
        connection.flush().unwrap();
        let mut bytes = Vec::new();
        loop {
            let mut chunk = [0; 4096];
            match server.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => bytes.extend_from_slice(&chunk[..n]),
                Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
                Err(e) => panic!("wire read: {e}"),
            }
        }
        let mut result = Vec::new();
        let word = |bytes: &[u8]| u32::from_ne_bytes(bytes.try_into().unwrap());
        let mut offset = 0;
        while offset < bytes.len() {
            let header = word(&bytes[offset + 4..offset + 8]);
            let size = (header >> 16) as usize;
            result.push((word(&bytes[offset..offset + 4]), header as u16,
                bytes[offset + 8..offset + size].chunks_exact(4).map(word).collect()));
            offset += size;
        }
        result
    }

    #[test]
    fn native_blur_regions_resize_capability_and_lifetime() {
        let (client, mut server) = UnixStream::pair().unwrap();
        server.set_nonblocking(true).unwrap();
        let connection = Connection::from_socket(client).unwrap();
        let queue = connection.new_event_queue::<WaylandClientStatePtr>();
        let qh = queue.handle();
        let registry = connection.display().get_registry(&qh, ());
        let compositor: wl_compositor::WlCompositor = registry.bind(1, 6, &qh, ());
        let ext: ext_background_effect_manager_v1::ExtBackgroundEffectManagerV1 = registry.bind(2, 1, &qh, ());
        let kde: org_kde_kwin_blur_manager::OrgKdeKwinBlurManager = registry.bind(3, 1, &qh, ());
        let surface = compositor.create_surface(&qh, ());
        let region = compositor.create_region(&qh, ());
        region.add(0, 0, 640, 480);
        let mut effects = BackgroundEffects::default();
        let mut blur = BackgroundBlur::default();
        requests(&connection, &mut server);

        assert!(!effects.supports_blur());
        blur.update(&effects, &surface, &qh, &region, true);
        assert!(requests(&connection, &mut server).is_empty(), "unsupported means no blur request");
        effects.ext = Some(ext.clone());
        effects.kde = Some(kde.clone());
        assert!(!effects.supports_blur(), "binding is not the ext blur capability");
        effects.blur = true;
        assert!(effects.supports_blur());
        blur.update(&effects, &surface, &qh, &region, true);
        let id = blur.ext.as_ref().unwrap().id().protocol_id();
        let wire = requests(&connection, &mut server);
        assert!(wire.contains(&(ext.id().protocol_id(), 1, vec![id, surface.id().protocol_id()])));
        assert!(wire.contains(&(id, 1, vec![region.id().protocol_id()])), "non-null ext blur region");
        assert!(blur.kde.is_none(), "prefer explicit ext capability");

        let resized = compositor.create_region(&qh, ());
        resized.add(0, 0, 960, 720);
        blur.update(&effects, &surface, &qh, &resized, true);
        let wire = requests(&connection, &mut server);
        assert!(wire.contains(&(resized.id().protocol_id(), 1, vec![0, 0, 960, 720])));
        assert!(wire.contains(&(id, 1, vec![resized.id().protocol_id()])));
        assert!(!wire.iter().any(|(sender, opcode, _)| *sender == ext.id().protocol_id() && *opcode == 1), "resize reuses effect");

        effects.blur = false;
        assert!(!effects.supports_blur(), "lost capability must not fall through to KDE");
        blur.update(&effects, &surface, &qh, &resized, true);
        assert!(requests(&connection, &mut server).contains(&(id, 0, vec![])), "remove effect on capability loss");
        assert!(blur.ext.is_none() && blur.kde.is_none());

        effects.ext = None; // older KWin's advertised legacy protocol
        assert!(effects.supports_blur());
        blur.update(&effects, &surface, &qh, &resized, true);
        let id = blur.kde.as_ref().unwrap().id().protocol_id();
        let wire = requests(&connection, &mut server);
        assert!(wire.contains(&(kde.id().protocol_id(), 0, vec![id, surface.id().protocol_id()])));
        assert!(wire.contains(&(id, 1, vec![resized.id().protocol_id()])));
        assert!(wire.contains(&(id, 0, vec![])), "KDE blur commit");
        blur.update(&effects, &surface, &qh, &resized, false);
        let wire = requests(&connection, &mut server);
        assert!(wire.contains(&(kde.id().protocol_id(), 1, vec![surface.id().protocol_id()])));
        assert!(wire.contains(&(id, 2, vec![])), "release after opaque fallback");
        assert!(blur.kde.is_none());

        // A recreated window gets new request objects; opaque first paint does not.
        let recreated = compositor.create_surface(&qh, ());
        effects.ext = Some(ext);
        effects.blur = true;
        blur.update(&effects, &recreated, &qh, &region, true);
        assert!(blur.ext.is_some());
        let id = blur.ext.as_ref().unwrap().id().protocol_id();
        blur.clear();
        assert!(requests(&connection, &mut server).contains(&(id, 0, vec![])));
        assert!(blur.ext.is_none());
    }
}


